async callback(req: Request, _res: Response): Promise<AuthUser> {
  const mockUserId = req.query.mockUserId as string

  if (!mockUserId) {
    throw new Error('Mock callback requires mockUserId parameter')
  }

  // Find the user by ID - reject if not found (no silent fallback)
  const user = this.mockUsers.find((u) => u.id === mockUserId)
  if (!user) {
    throw new Error(`Mock user not found: ${mockUserId}`)
  }

  // Save to session
  this.saveUserToSession(req, user)

  return user
}

